(function(){"use strict";let hasSessionAccess=false;let checkInterval=null;function initAdminPath(){const secretPathField=document.getElementById("jform_params_secret_path");const blockDirectYes=document.getElementById("jform_params_block_direct1");const blockDirectNo=document.getElementById("jform_params_block_direct0");const urlDisplayContainer=secretPathField?.closest(".control-group")?.nextElementSibling;const urlDisplayField=urlDisplayContainer?.querySelector(".alert");if(!secretPathField||!blockDirectYes||!blockDirectNo||!urlDisplayField){return}const siteUrl=window.location.origin+"/administrator";const warningContainer=createWarningContainer();function createWarningContainer(){const container=document.createElement("div");container.id="adminpath_warning";container.style.cssText="display:none;margin-top:12px;padding:12px;background:#fff3cd;border-left:4px solid #ffc107;color:#856404;font-size:14px;border-radius:4px;";container.innerHTML="";urlDisplayField.parentNode.insertBefore(container,urlDisplayField.nextSibling);return container}function updateUrlDisplay(){const secretParam=secretPathField.value.trim();let fullUrl=siteUrl;if(secretParam){fullUrl+="?"+encodeURIComponent(secretParam)}else{fullUrl+="?[secret-parameter]"}const labelText=Joomla.Text._("PLG_SYSTEM_ADMINPATH_YOUR_ADMIN_URL");const copyText=Joomla.Text._("PLG_SYSTEM_ADMINPATH_COPY_LINK");console.log(labelText);urlDisplayField.innerHTML=`\n                <div style="display:flex;flex-direction:column;gap:12px;">\n                    <div>\n                        <strong>${labelText}:</strong>\n                    </div>\n                    <div style="display:flex;gap:8px;align-items:center;">\n                        <a href="${fullUrl}" target="_blank" style="flex:1;text-decoration:none;color:#007bff;font-weight:500;word-break:break-all;" id="adminpath_link">\n                            ${fullUrl}\n                        </a>\n                        <button type="button" \n                                class="btn btn-sm btn-secondary" \n                                onclick="copyAdminUrl('${fullUrl}', event)"\n                                title="${copyText}"\n                                style="white-space:nowrap;">\n                            ${copyText}\n                        </button>\n                    </div>\n                </div>\n            `}function checkSessionStatus(){Joomla.request({url:"index.php?option=com_ajax&plugin=adminpath&group=system&format=json",method:"POST",headers:{"Cache-Control":"no-cache","Content-Type":"application/json"},data:new URLSearchParams({option:"com_ajax",plugin:"adminpath",group:"system",format:"json"}).toString(),onSuccess:response=>{let data=JSON.parse(response);if(data.success){hasSessionAccess=data.data;updateWarningDisplay()}}})}function updateWarningDisplay(){if(blockDirectYes.checked&&!hasSessionAccess){const warningText=typeof Joomla!=="undefined"&&Joomla.Text?Joomla.Text._("PLG_SYSTEM_ADMINPATH_WARNING_BLOCK",'<strong style="color:#dc3545;">⚠️ WARNING:</strong> Direct access is blocked but you don\'t have session access! <strong>Click the link above</strong> to open admin panel in new tab, then return and save.'):'<strong style="color:#dc3545;">⚠️ WARNING:</strong> Direct access is blocked but you don\'t have session access! <strong>Click the link above</strong> to open admin panel in new tab, then return and save.';warningContainer.innerHTML=warningText;warningContainer.style.display="block";let pulseCount=0;const pulseInterval=setInterval(()=>{warningContainer.style.borderColor=pulseCount%2===0?"#dc3545":"#ffc107";pulseCount++;if(pulseCount>6){clearInterval(pulseInterval);warningContainer.style.borderColor="#ffc107"}},500)}else{warningContainer.style.display="none"}}function startChecking(){if(checkInterval){clearInterval(checkInterval)}checkSessionStatus();checkInterval=setInterval(checkSessionStatus,3e3)}function stopChecking(){if(checkInterval){clearInterval(checkInterval);checkInterval=null}warningContainer.style.display="none"}blockDirectYes.addEventListener("click",function(){startChecking()});blockDirectNo.addEventListener("click",function(){stopChecking()});if(blockDirectYes.checked){startChecking()}updateUrlDisplay();let timeout;secretPathField.addEventListener("input",function(){clearTimeout(timeout);timeout=setTimeout(updateUrlDisplay,300)})}window.copyAdminUrl=function(url,event){navigator.clipboard.writeText(url).then(function(){const originalText=event.currentTarget.innerHTML;const successText=typeof Joomla!=="undefined"&&Joomla.Text?Joomla.Text._("PLG_SYSTEM_ADMINPATH_COPIED","Copied!"):"Copied!";event.currentTarget.innerHTML=successText;event.currentTarget.classList.add("btn-success");setTimeout(function(){event.currentTarget.innerHTML=originalText;event.currentTarget.classList.remove("btn-success")},2e3)}).catch(function(err){console.error("Could not copy text: ",err)})};function prefillAllowedIp(){const params=new URLSearchParams(window.location.search);const addIp=params.get("add_ip");if(!addIp)return;const field=document.getElementById("jform_params_allowed_ips");if(!field)return;const current=field.value.trim();const ips=current?current.split(/[\\r\\n,;]+/).map(s=>s.trim()).filter(Boolean):[];if(!ips.includes(addIp)){ips.push(addIp);field.value=ips.join("\\n")}if(typeof Joomla!=="undefined"&&Joomla.renderMessages){Joomla.renderMessages({notice:["IP "+addIp+" "+(Joomla.Text?Joomla.Text._("PLG_SYSTEM_ADMINPATH_IP_ADDED","добавлен в белый список. Сохраните настройки."):"добавлен в белый список. Сохраните настройки.")]})}}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",function(){initAdminPath();prefillAllowedIp()})}else{initAdminPath();prefillAllowedIp()}})();